----------------------------------------------------------------------
-- SCRIPT 2: RUNTIME (run AFTER the plane is spawned, with an Anchor block on it, after script 1 painted/sized the plates)
-- Nothing is client-only: the plates are detached and welded with the game's own remotes (UnanchorWelds / MotorLock) and
-- moved with physics you own (BodyPosition/BodyGyro + BulkMoveTo), so EVERY player sees the Tyrant walk, run, jump and swing.
-- Only your camera, your HUD and hiding your own avatar are local.
----------------------------------------------------------------------
local function main()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS = game:GetService("UserInputService")
local RS = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")

local G = (getgenv and getgenv()) or _G
if G.__TyrantStop then pcall(G.__TyrantStop, "replaced by a new run") end

local CFG = {
	WALK_SPEED = 10,       -- studs/s
	RUN_SPEED = 21,        -- studs/s (SHIFT / RUN button)
	TURN_RATE = 9,         -- how fast the body turns to the move direction
	JUMP_POWER = 50,
	GRAVITY = 140,
	CLIP_BLEND = 0.2,      -- seconds of crossfade between animations
	UPDATE_HZ = 60,
	FOLLOW_P = 100000,
	FOLLOW_D = 120,
	CAM_MIN = 22,
	CAM_HEIGHT = 9,
	SPAWN_DIST = 40,       -- studs in front of you where it appears
	HIDE_SELF = true,
	PLANE_NAME = nil,      -- e.g. "Name Aircraft" if your plane is not named after Player.Name
}
local Player = Players.LocalPlayer
local Character = Player.Character or Player.CharacterAdded:Wait()
local RealHum = Character:WaitForChild("Humanoid")
local RealRoot = Character:WaitForChild("HumanoidRootPart")

local V = Vector3.new
local ZERO = Vector3.zero
local U = SCALE
local RAD, CF, ANGLES = math.rad, CFrame.new, CFrame.Angles
local IDENT = CFrame.identity

local alive = true
local conns = {}
local function track(c) conns[#conns + 1] = c return c end
local followers, shells, toDetach = {}, {}, {}
local holds = {}   -- temporary position holders on released plates (see FIX 1)
local camPart

-- HUD (local only: it is just a text box for you) ----------------------
local HUD = {}
local hud = Instance.new("ScreenGui")
hud.Name = "TyrantHUD"
hud.ResetOnSpawn = false
local hudLabel = Instance.new("TextLabel")
hudLabel.Size = UDim2.new(0, 520, 0, 190)
hudLabel.Position = UDim2.new(0, 10, 0, 60)
hudLabel.BackgroundColor3 = Color3.new(0, 0, 0)
hudLabel.BackgroundTransparency = 0.4
hudLabel.TextColor3 = Color3.new(1, 1, 1)
hudLabel.Font = Enum.Font.Code
hudLabel.TextSize = 13
hudLabel.TextXAlignment = Enum.TextXAlignment.Left
hudLabel.TextYAlignment = Enum.TextYAlignment.Top
hudLabel.TextWrapped = true
hudLabel.Parent = hud
pcall(function() hud.Parent = (gethui and gethui()) or Player:WaitForChild("PlayerGui") end)
local function say(...)
	local t = table.pack(...)
	for i = 1, t.n do t[i] = tostring(t[i]) end
	local m = table.concat(t, " ")
	print("[Tyrant] " .. m)
	table.insert(HUD, m)
	while #HUD > 9 do table.remove(HUD, 1) end
	hudLabel.Text = table.concat(HUD, "\n") .. "\n\n"
end

----------------------------------------------------------------------
-- SHUTDOWN (gives the camera back)
----------------------------------------------------------------------
local function restoreCamera()
	local cam = Workspace.CurrentCamera
	if not cam then return end
	pcall(function()
		Player.CameraMinZoomDistance = 0.5
		Player.CameraMaxZoomDistance = 128
		Player.CameraMode = Enum.CameraMode.Classic
		cam.CameraType = Enum.CameraType.Custom
		local ch = Player.Character
		local hum = ch and ch:FindFirstChildOfClass("Humanoid")
		if hum then cam.CameraSubject = hum end
	end)
end

local function shutdown(reason)
	if not alive then return end
	alive = false
	print("[Tyrant] stopped: " .. tostring(reason))
	for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
	if G.__TyrantStop == shutdown then G.__TyrantStop = nil end
	pcall(function() camPart:Destroy() end)
	pcall(function() hud:Destroy() end)
	for _, f in ipairs(followers) do
		pcall(function() if f.bp then f.bp:Destroy() end if f.bg then f.bg:Destroy() end end)
	end
	for _, h in pairs(holds) do pcall(function() h:Destroy() end) end
	pcall(function()
		for _, d in ipairs(Character:GetDescendants()) do
			if d:IsA("BasePart") then d.LocalTransparencyModifier = 0 end
		end
		RealRoot.Anchored = false
		RealHum.WalkSpeed = 16
		RealHum.AutoRotate = true
		local an = Character:FindFirstChild("Animate")
		if an then an.Disabled = false end
	end)
	pcall(function() game:GetService("Lighting").GlobalShadows = true end)
	restoreCamera()
	task.spawn(function()
		for _ = 1, 40 do
			local ch = Player.Character
			local hum = ch and ch:FindFirstChildOfClass("Humanoid")
			local cam = Workspace.CurrentCamera
			if cam and (not hum or cam.CameraSubject ~= hum or cam.CameraType ~= Enum.CameraType.Custom
				or Player.CameraMinZoomDistance > 1) then
				restoreCamera()
			end
			task.wait(0.12)
		end
	end)
end
G.__TyrantStop = shutdown

local aircraft = Workspace:WaitForChild(CFG.PLANE_NAME or (Player.Name .. " Aircraft"), 10)
if not aircraft then
	-- fallback: the only model/folder in Workspace with 50+ SPart (the unspawned plot "PIayerAircraft" is excluded)
	local found, many = nil, false
	for _, m in ipairs(Workspace:GetChildren()) do
		if m.Name ~= "PIayerAircraft" and (m:IsA("Model") or m:IsA("Folder")) then
			local n = 0
			for _, d in ipairs(m:GetDescendants()) do if d.Name == "SPart" then n = n + 1 end end
			if n >= 50 then
				if found then many = true end
				found = m
			end
		end
	end
	if many then found = nil warn("[Tyrant] several planes found - set CFG.PLANE_NAME = \"<name> Aircraft\"") end
	aircraft = found
end
assert(aircraft, "[Tyrant] no spawned aircraft found")
local seatPart = RealHum.SeatPart or aircraft:FindFirstChildWhichIsA("VehicleSeat", true) or aircraft:FindFirstChildWhichIsA("Seat", true)
local Remotes = RS:WaitForChild("Remotes")
local unweldRemote = Remotes:WaitForChild("UnanchorWelds")
local UpdateValue = Remotes:WaitForChild("UpdateValue")
local function unweld(p) unweldRemote:FireServer(p, "Break") end

for _, p in ipairs(aircraft:GetDescendants()) do
	if p:IsA("BasePart") then p.CanCollide = false end
end
local SELF_GROUP = "TyrantSelf"
local groupOk = pcall(function()
	local PS = game:GetService("PhysicsService")
	pcall(function() PS:RegisterCollisionGroup(SELF_GROUP) end)
	PS:CollisionGroupSetCollidable(SELF_GROUP, SELF_GROUP, false)
end)
local function setGroup(p) if groupOk then pcall(function() p.CollisionGroup = SELF_GROUP end) end end

----------------------------------------------------------------------
-- COLLECT + MATCH SMALLPARTS (size + colour)
----------------------------------------------------------------------
local function collect()
	local list, viaCfg = {}, 0
	for _, o in ipairs(aircraft:GetDescendants()) do
		if o.Name == "SmallPart" and o:IsA("Model") then
			local p = o:FindFirstChild("SPart")
			if p then
				local cfg = o:FindFirstChild("Configuration")
				local sx, sy, sz = cfg and cfg:FindFirstChild("Size X"), cfg and cfg:FindFirstChild("Size Y"), cfg and cfg:FindFirstChild("Size Z")
				local gx, gy, gz = sx and tonumber(sx.Value), sy and tonumber(sy.Value), sz and tonumber(sz.Value)
				if gx and gy and gz then viaCfg = viaCfg + 1
				else gx, gy, gz = gridOf(p.Size.X), gridOf(p.Size.Y), gridOf(p.Size.Z) end
				local r, g, b = c255(p.Color)
				table.insert(list, { part = p, gx = gx, gy = gy, gz = gz, r = r, g = g, b = b, key = makeKey(gx, gy, gz, r, g, b), used = false })
			end
		end
	end
	return list, viaCfg
end

say("collecting SmallParts...")
local all, viaCfg = collect()
local waited = 0
while #all < #BOXES and waited < 15 do
	task.wait(1) waited = waited + 1
	all, viaCfg = collect()
end
local count = math.min(#BOXES, #all)
say(("need %d, found %d SmallParts (%d read size config)"):format(#BOXES, #all, viaCfg))
if #BOXES > #all then warn(("missing %d SmallParts"):format(#BOXES - #all)) end

local exact, byColor = {}, {}
for _, rec in ipairs(all) do
	exact[rec.key] = exact[rec.key] or {}
	table.insert(exact[rec.key], rec)
	local ck = rec.r .. "," .. rec.g .. "," .. rec.b
	byColor[ck] = byColor[ck] or {}
	table.insert(byColor[ck], rec)
end
local assigned, leftovers, exactHits = {}, {}, 0
for i = 1, count do
	local list = exact[BOXES[i].key]
	local rec
	while list and #list > 0 do
		local r = table.remove(list)
		if not r.used then rec = r break end
	end
	if rec then rec.used = true assigned[i] = rec.part exactHits = exactHits + 1
	else table.insert(leftovers, i) end
end
local function sizeScore(rec, t)
	return math.abs(rec.gx - t.gx) + math.abs(rec.gy - t.gy) + math.abs(rec.gz - t.gz)
end
for n, i in ipairs(leftovers) do
	local t, best, bestS = BOXES[i], nil, nil
	for _, rec in ipairs(byColor[t.r .. "," .. t.g .. "," .. t.b] or {}) do
		if not rec.used then
			local s = sizeScore(rec, t)
			if not bestS or s < bestS then best, bestS = rec, s end
		end
	end
	if not best then
		for _, rec in ipairs(all) do
			if not rec.used then
				local s = sizeScore(rec, t) + (math.abs(rec.r - t.r) + math.abs(rec.g - t.g) + math.abs(rec.b - t.b)) / 255
				if not bestS or s < bestS then best, bestS = rec, s end
			end
		end
	end
	if best then best.used = true assigned[i] = best.part end
	if n % 100 == 0 then task.wait() end
end
say(("matched: %d exact, %d closest"):format(exactHits, #leftovers))
if #leftovers > count * 0.1 then warn("many parts had no exact match - did script 1 finish, same SCALE?") end


----------------------------------------------------------------------
-- SKELETON (every bone is a world frame that comes straight from the clip data)
----------------------------------------------------------------------
local W = {}

----------------------------------------------------------------------
-- BUILD FOLLOWERS + ROCK POOL
----------------------------------------------------------------------
local function makeFollower(part)
	local bg = Instance.new("BodyGyro")
	bg.MaxTorque = V(1e6, 1e6, 1e6)
	bg.D, bg.P = 75, 15000
	bg.CFrame = part.CFrame
	bg.Parent = part
	local bp = Instance.new("BodyPosition")
	bp.MaxForce = V(1e7, 1e7, 1e7)
	bp.P, bp.D = CFG.FOLLOW_P, CFG.FOLLOW_D
	bp.Position = part.Position
	bp.Parent = part
	return bp, bg
end

for i = 1, count do
	local box, p = BOXES[i], assigned[i]
	if p then
		p.CanCollide = false
		p.Anchored = false
		table.insert(toDetach, p)
		if box.bone == "ammo" then
			table.insert(shells, { part = p })
		else
			table.insert(followers, { part = p, bone = box.bone, cf = box.cf })
		end
	end
end


-- (FIX 3) the anchor block is needed later; check it BEFORE releasing 3390 plates (it used to be asserted after)
local ab = aircraft:FindFirstChild("AnchoredBlockStd")
local motorBlock = (ab and ab:FindFirstChild("AnchoredStd")) or aircraft:FindFirstChild("MotorBlock")
assert(motorBlock, "[Tyrant] place an Anchor block (AnchoredBlockStd) on your plane first")
local motorLock = RS:WaitForChild("BlockRemotes"):WaitForChild("MotorLock")

local function isAlive(p) return p.Parent ~= nil and p:IsDescendantOf(Workspace) end
local function dropHold(p)
	local h = holds[p]
	if h then holds[p] = nil pcall(function() h:Destroy() end) end
end

-- (FIX 1) a released plate had NOTHING holding it until its bone got a follower (25+ s later). It fell out of the map,
-- the engine destroyed it (FallenPartsDestroyHeight) and every later call said "SPart is not parented to the Workspace".
-- Now each plate gets a temporary BodyPosition (physics you own, so it replicates) BEFORE it is released.
say(("holding %d parts in place..."):format(#toDetach))
for i, p in ipairs(toDetach) do
	pcall(function()
		local hp = Instance.new("BodyPosition")
		hp.MaxForce = V(1e7, 1e7, 1e7)
		hp.P, hp.D = CFG.FOLLOW_P, CFG.FOLLOW_D
		hp.Position = p.Position
		hp.Parent = p
		holds[p] = hp
	end)
	if i % 100 == 0 then task.wait() end
end

-- detach everything from the plane (throttled)
say(("detaching %d parts..."):format(#toDetach))
for i, p in ipairs(toDetach) do
	unweld(p)
	if i % 6 == 0 then task.wait() end
end
local t0 = os.clock()
local stuck = 0
repeat
	task.wait(0.2)
	local bad = {}
	for i, p in ipairs(toDetach) do
		if isAlive(p) then   -- (FIX 2) never call GetConnectedParts on a dead part: it only spams warnings
			local ok, conn = pcall(p.GetConnectedParts, p, true)
			if ok then
				for _, q2 in ipairs(conn) do if q2 ~= p then bad[#bad + 1] = p break end end
			end
		end
		if i % 300 == 0 then task.wait() end
	end
	stuck = #bad
	if stuck == 0 then break end
	for i, p in ipairs(bad) do unweld(p) if i % 6 == 0 then task.wait() end end
until os.clock() - t0 > 45
if stuck > 0 then warn(stuck .. " parts still linked to the plane") end

-- (FIX 2) did the plates survive being released? If not, say so clearly and stop instead of "welding" ghosts
do
	local deadN = 0
	for _, f in ipairs(followers) do if not isAlive(f.part) then deadN = deadN + 1 end end
	if deadN > 0 then
		warn(("[Tyrant] %d/%d plates are not in the Workspace any more (plane still there: %s)")
			:format(deadN, #followers, tostring(aircraft:IsDescendantOf(Workspace))))
	end
	if deadN > #followers * 0.3 then
		shutdown(("%d plates were destroyed after being released (they fell out of the map or the plane was removed)"):format(deadN))
		return
	end
end

-- one driver part per bone (first LIVE plate); every other plate of the bone is welded to it on the server
local WELD_FLIP = true
local function serverWeld(p1, p2, cf)
	motorLock:FireServer("MotorWeld", motorBlock, true, p1, p2, cf, true)
end
local byBone, drivers = {}, {}
local function buildGroups()
	byBone, drivers = {}, {}
	for _, f in ipairs(followers) do
		if isAlive(f.part) then
			local d = drivers[f.bone]
			if not d then
				drivers[f.bone] = f
				f.group = {}
				byBone[f.bone] = { f }
			else
				table.insert(d.group, f)
			end
		end
	end
end
buildGroups()
say("welding parts into bone assemblies...")
local wcount = 0
local function weldGroup(d, only)
	local inv = d.cf:Inverse()
	for _, f in ipairs(d.group) do
		if not only or only[f] then
			local rel = inv * f.cf
			if WELD_FLIP then rel = rel:Inverse() end
			serverWeld(f.part, d.part, rel)
			wcount = wcount + 1
			if wcount % 5 == 0 then task.wait() end
		end
	end
end
for _, d in pairs(drivers) do weldGroup(d) end
local confirmed, deadFollowers = 0, 0
for pass = 1, 6 do
	task.wait(pass == 1 and 1.2 or 2.5)   -- check early: the temporary holds must not fight the welds for long
	-- (FIX 2) if a driver died, elect another live plate of that bone and weld the group to it
	local oldDrv, lost = {}, false
	for bone, d in pairs(drivers) do
		oldDrv[bone] = d
		if not isAlive(d.part) then lost = true end
	end
	if lost then
		buildGroups()
		for bone, d in pairs(drivers) do
			if oldDrv[bone] ~= d then
				say(("pass %d: %s lost its driver, new one elected"):format(pass, bone))
				weldGroup(d)
			end
		end
	end
	local total = 0
	confirmed, deadFollowers = 0, 0
	for bone, d in pairs(drivers) do
		local ok, conn = pcall(d.part.GetConnectedParts, d.part, true)
		local set = {}
		if ok then for _, p in ipairs(conn) do set[p] = true end end
		local missingW, miss = {}, 0
		for _, f in ipairs(d.group) do
			if not isAlive(f.part) then
				deadFollowers = deadFollowers + 1
			elseif set[f.part] then
				confirmed = confirmed + 1
				dropHold(f.part)   -- welded: the temporary holder is not needed (and must not fight the weld)
			else
				missingW[f] = true
				miss = miss + 1
			end
		end
		if miss > 0 then
			say(("pass %d: %s missing %d/%d"):format(pass, bone, miss, #d.group))
			total = total + miss
			weldGroup(d, missingW)
		end
	end
	if total == 0 then say("all welds confirmed") break end
end

-- (FIX 4) report what was REALLY confirmed (the old "welded N parts" was only a counter of weld requests, retries included)
local groupTotal, nBones = 0, 0
for _, d in pairs(drivers) do groupTotal = groupTotal + #d.group nBones = nBones + 1 end
if groupTotal > 0 and confirmed < groupTotal * 0.5 then
	shutdown(("only %d/%d plates ended up welded (dead: %d, weld requests sent: %d). Stopped instead of running with a broken body.")
		:format(confirmed, groupTotal, deadFollowers, wcount))
	return
end

for _, d in pairs(drivers) do
	dropHold(d.part)
	d.bp, d.bg = makeFollower(d.part)
end
for _, s in ipairs(shells) do
	dropHold(s.part)
	pcall(function() s.bp, s.bg = makeFollower(s.part) end)
end
for i, f in ipairs(followers) do
	pcall(function()
		f.part.CastShadow = false
		f.part.CanTouch = false
		f.part.CanQuery = false
	end)
	if i % 300 == 0 then task.wait() end
end
for _, s in ipairs(shells) do
	pcall(function() s.part.CastShadow = false s.part.CanQuery = false end)
end
say(("%d/%d plates confirmed in %d bone assemblies | %d weld requests | shells %d"):format(confirmed, groupTotal, nBones, wcount, #shells))
for _, f in ipairs(followers) do setGroup(f.part) end
for _, s in ipairs(shells) do setGroup(s.part) end
say(groupOk and "self-collision off" or "collision groups unavailable (self-collision stays on)")

----------------------------------------------------------------------
-- RIG: 15 rigid bones. Every plate keeps its rest-pose CFrame (model space, metres*SCALE, feet at origin, faces -Z);
-- the baked clips give each bone's transform relative to rest, so a plate's world CFrame is  root * pose[bone] * plate.cf
----------------------------------------------------------------------
local NB = #BONE_ORDER
local clips = {}
local B64 = {}
do local AL = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/" for i = 1, 64 do B64[AL:byte(i)] = i - 1 end end
local function getClip(name)
	local c = clips[name]
	if c then return c end
	local d = CLIPDATA[name]
	if not d then return nil end
	local s, p = d.data, 1
	local function rd() local v = B64[s:byte(p)] * 64 + B64[s:byte(p + 1)] p = p + 2 return v / 4095 end
	local frames = {}
	for f = 1, d.n do
		local row = {}
		for b = 1, NB do
			local tx, ty, tz = rd() * 8 - 4, rd() * 8 - 4, rd() * 8 - 4
			local x, y, z = rd() * 2 - 1, rd() * 2 - 1, rd() * 2 - 1
			local w = math.sqrt(math.max(0, 1 - x * x - y * y - z * z))
			row[b] = CF(tx * U, ty * U, tz * U, x, y, z, w)
		end
		frames[f] = row
	end
	c = { fps = d.fps, n = d.n, f = frames, ref = math.max(d.ref, 0.1), loop = (name == "idle" or name == "walk" or name == "run") }
	clips[name] = c
	return c
end
local function samplePose(c, t, out)
	local fp, i, j, a = t * c.fps, 0, 0, 0
	if c.loop then
		fp = fp % c.n
		i = math.floor(fp) a = fp - i
		j = i % c.n + 1 i = i + 1
	else
		fp = math.clamp(fp, 0, c.n - 1)
		i = math.floor(fp) a = fp - i
		j = math.min(i + 2, c.n) i = i + 1
	end
	local fa, fb = c.f[i], c.f[j]
	for b = 1, NB do out[b] = fa[b]:Lerp(fb[b], a) end
end
local function unit(v, fb) local m = v.Magnitude if m < 1e-6 then return fb or V(0, 0, -1) end return v / m end
local function wrap(a) return (a + math.pi) % (2 * math.pi) - math.pi end
local function groundBelow(p, maxLen)
	local len = math.min(maxLen or 3000, p.Y - (Workspace.FallenPartsDestroyHeight + 20))
	if len <= 0 then return nil end
	local res = Workspace:Raycast(p, V(0, -len, 0), rayParams)
	return res and res.Position.Y or nil
end
local function listExclude()
	local l = { Character, aircraft }
	for _, pl2 in ipairs(Players:GetPlayers()) do if pl2.Character then table.insert(l, pl2.Character) end end
	return l
end
local rayParams
rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
rayParams.FilterDescendantsInstances = listExclude()
