local bulkParts, bulkCFs, lastN = {}, {}, 0
local moveAcc, fastCam, hideT = 0, 0, 0
local function pruneDead()
	local nb, live = {}, 0
	for bone, d in pairs(drivers) do
		if d.part.Parent and d.bp and d.bg then nb[bone] = { d } live = live + 1 + #d.group end
	end
	byBone = nb
	return live
end
local function setClip(name)
	if name == curClip then return end
	for b = 1, NB do fromPose[b] = pose[b] end
	curClip, curT, blend = name, 0, 0
end
local function kbDir()
	local look = Workspace.CurrentCamera.CFrame.LookVector
	local fwd = unit(V(look.X, 0, look.Z), V(0, 0, -1))
	local right = fwd:Cross(V(0, 1, 0))
	local d = ZERO
	if UIS:IsKeyDown(Enum.KeyCode.W) then d = d + fwd end
	if UIS:IsKeyDown(Enum.KeyCode.S) then d = d - fwd end
	if UIS:IsKeyDown(Enum.KeyCode.D) then d = d + right end
	if UIS:IsKeyDown(Enum.KeyCode.A) then d = d - right end
	return d
end
----------------------------------------------------------------------
-- FUNCTION OF EVERY ANIMATION. All of it moves/rotates the Tyrant itself (server-replicated physics), so everybody sees it.
--   lock  = attack: cannot be cancelled, lunges forward          stun = frozen reaction (hit / knocked down / landing / intro)
--   lunge = peak forward speed (studs/s)   dash = charge speed   turn = total yaw rotated during the clip (rad, + = left)
--   rage  = taunt: run/walk speed x1.35 for N seconds           use = fires nearby ProximityPrompts / ClickDetectors (server-side)
--   cut   = seconds after which a long clip is ended early       after = clip played when it ends (get-up)
-- Not listed = emote (cancelled when you move). Automatic ones: idle fidgets (react_lookaround/fixhat), land (hard fall), glide (long fall),
-- ladder_* (walk into a wall to climb it), stun/down (when YOUR health drops), emerge_2 (intro on start).
----------------------------------------------------------------------
local PI = math.pi
local ACT = {
	att1_1 = { lock = true, lunge = 14 }, att1_2 = { lock = true, lunge = 16 }, att1 = { lock = true, lunge = 18 },
	att2_1 = { lock = true, lunge = 12 }, att2_2 = { lock = true, lunge = 14 }, att2 = { lock = true, lunge = 16 },
	att3 = { lock = true, lunge = 22 }, att4 = { lock = true, lunge = 26 }, att5 = { lock = true, lunge = 28 }, att6 = { lock = true, lunge = 28 },
	att_charge_1 = { lock = true, dash = 55 }, att_charge_2 = { lock = true, dash = 70 }, att_charge_3 = { lock = true, dash = 45 },
	att_grab = { lock = true, lunge = 20 }, att_grab_hit_1 = { lock = true, lunge = 6, use = true }, att_grab_hit_2 = { lock = true, lunge = 6, use = true },
	att_turn_l90 = { lock = true, turn = PI / 2, lunge = 8 }, att_turn_r90 = { lock = true, turn = -PI / 2, lunge = 8 },
	att_turn180_1 = { lock = true, turn = PI, lunge = 6 }, att_turn180_2 = { lock = true, turn = -PI, lunge = 6 },
	turn_l90 = { turn = PI / 2 }, turn_r90 = { turn = -PI / 2 }, turn_180_1 = { turn = PI }, turn_180_2 = { turn = -PI },
	react_taunt1 = { rage = 8, cut = 4 }, react_taunt2 = { rage = 8, cut = 4 }, react_taunt3 = { rage = 8, cut = 4 },
	stun1_f = { stun = true, cut = 2.5 }, stun1_b = { stun = true, cut = 2.5 }, stun2_f = { stun = true, cut = 2.5 }, stun2_b = { stun = true, cut = 2.5 },
	stun3_f = { stun = true, cut = 3 }, stun3_b = { stun = true, cut = 3 }, stun_arm_r = { stun = true, cut = 2.5 }, stun_arm_l = { stun = true, cut = 2.5 },
	stun_head = { stun = true, cut = 3 }, stun_shock_1_f = { stun = true, cut = 3.5 }, stun_shock_1_b = { stun = true, cut = 3.5 }, stun_shock_2 = { stun = true, cut = 3.5 },
	down_1 = { stun = true, cut = 4, after = "emerge_1" }, down_2 = { stun = true, cut = 3, after = "emerge_1" }, down_3 = { stun = true, cut = 5, after = "emerge_1" },
	land = { stun = true, cut = 1.3 }, emerge_1 = { stun = true, cut = 2.5 }, emerge_2 = { stun = true, cut = 4 },
	opendoors = { use = true, cut = 3 },
}
local COMBO = { ATTACK = { "att1_1", "att1_2", "att1" }, SLASH = { "att2_1", "att2_2", "att2" } }
local comboI, comboT = { ATTACK = 0, SLASH = 0 }, 0
local HEAVY = { "att3", "att4", "att5", "att6" }
local CHARGE = { "att_charge_1", "att_charge_2", "att_charge_3" }
local FIDGET = { "react_lookaround1", "react_lookaround2", "react_lookaround3", "react_fixhat1", "react_fixhat2" }
local STUN_L = { "stun1_f", "stun1_b", "stun2_f", "stun2_b", "stun_arm_r", "stun_arm_l", "stun_head" }
local STUN_M = { "stun3_f", "stun3_b", "stun_shock_1_f", "stun_shock_1_b", "stun_shock_2" }
local DOWN = { "down_1", "down_2", "down_3" }
local function pick(t) return t[math.random(1, #t)] end
local rageT, idleT, idleNext, fallT, climb = 0, 0, 12, 0, nil
local function useNearby(pos0, fwd0)
	local op = OverlapParams.new()
	op.FilterType = Enum.RaycastFilterType.Exclude
	op.FilterDescendantsInstances = listExclude()
	local n = 0
	for _, p in ipairs(Workspace:GetPartBoundsInRadius(pos0 + V(0, 6, 0) + fwd0 * 6, 16, op)) do
		local root = p.Parent
		local pr = p:FindFirstChildWhichIsA("ProximityPrompt", true) or (root and root:FindFirstChildWhichIsA("ProximityPrompt", true))
		local cd = p:FindFirstChildWhichIsA("ClickDetector", true) or (root and root:FindFirstChildWhichIsA("ClickDetector", true))
		if pr and fireproximityprompt then pcall(fireproximityprompt, pr) n = n + 1 end
		if cd and fireclickdetector then pcall(fireclickdetector, cd) n = n + 1 end
		if n >= 6 then break end
	end
	say(n > 0 and ("used %d object(s)"):format(n) or "nothing to use nearby")
end
local atk = nil
local function startAct(n, force)
	if atk and atk.fixed and not force then return false end
	local c = getClip(n)
	if not c then return false end
	local sp = ACT[n] or {}
	atk = { name = n, sp = sp, dur = math.min((c.n - 1) / c.fps, sp.cut or 1e9), fixed = (sp.lock or sp.stun) and true or false }
	curT = 0
	if curClip == n then curClip = "" end
	if sp.rage then rageT = sp.rage end
	if sp.use then
		local f = V(-math.sin(yaw), 0, -math.cos(yaw))
		useNearby(pos, f)
	end
	return true
end
local function wallAhead(h, dist)
	local f = V(-math.sin(yaw), 0, -math.cos(yaw))
	local r = Workspace:Raycast(pos + V(0, h, 0), f * dist, rayParams)
	if r and math.abs(r.Normal.Y) < 0.35 then return r end
	return nil
end
local lastHealth = RealHum.Health
track(RealHum.HealthChanged:Connect(function(h)
	local dmg = lastHealth - h
	lastHealth = h
	if dmg <= 0 or not alive then return end
	if atk and atk.sp.lock then return end   -- attacks have super armour
	local frac = dmg / math.max(1, RealHum.MaxHealth)
	climb = nil
	if frac >= 0.35 then startAct(pick(DOWN), true)
	elseif frac >= 0.15 then startAct(pick(STUN_M), true)
	else startAct(pick(STUN_L), true) end
end))
local function frame(dt)
	dt = math.min(dt, 0.1)
	local cam = Workspace.CurrentCamera
	local fwd = V(-math.sin(yaw), 0, -math.cos(yaw))
	-- ===== input -> wish direction (keyboard, gamepad and the mobile thumbstick) =====
	local wish = kbDir()
	if wish.Magnitude < 0.1 then
		local md = RealHum.MoveDirection
		wish = V(md.X, 0, md.Z)
	end
	if wish.Magnitude > 1 then wish = wish.Unit end
	local wantRun = runToggle or shiftHeld
	comboT = comboT + dt
	for _, k in ipairs({ "ATTACK", "SLASH" }) do
		if actions[k] then
			if comboT > 2.2 then comboI[k] = 0 end
			comboI[k] = comboI[k] % #COMBO[k] + 1
			if startAct(COMBO[k][comboI[k]]) then comboT = 0 end
			actions[k] = nil
		end
	end
	if actions.HEAVY then startAct(pick(HEAVY)) actions.HEAVY = nil end
	if actions.CHARGE then startAct(pick(CHARGE)) actions.CHARGE = nil end
	if actions.TAUNT then startAct("react_taunt" .. math.random(1, 3)) actions.TAUNT = nil end
	if actions.USE then startAct("opendoors") actions.USE = nil end
	if actions.PLAY then startAct(actions.PLAY) actions.PLAY = nil end
	if atk and not atk.fixed and wish.Magnitude > 0.3 then atk = nil end
	rageT = math.max(0, rageT - dt)
	local spd = (wantRun and CFG.RUN_SPEED or CFG.WALK_SPEED) * (rageT > 0 and 1.35 or 1)
	-- ===== climbing: walk into a tall wall =====
	if not climb and not atk and wish.Magnitude > 0.5 and wish:Dot(fwd) > 0.5 then
		local w1, w2 = wallAhead(5, 5), wallAhead(14, 6)
		if w1 and w2 then
			climb = { clip = "ladder_start", t = 0, phase = "start", dur = 1.2, side = "l" }
			vel = ZERO
			yaw = math.atan2(w1.Normal.X, w1.Normal.Z)   -- face the wall
		end
	end
	local target
	local act = atk
	local p = act and math.clamp(curT / act.dur, 0, 1) or 0
	if climb then
		target = ZERO
		climb.t = climb.t + dt
		vy, grounded = 0, false
		if wish:Dot(fwd) < -0.3 or actions.JUMP then climb = nil vy = 10
		elseif climb.phase == "start" then
			if climb.t >= climb.dur then climb.phase, climb.clip, climb.t, climb.dur = "up", "ladder_up_l", 0, 1.4 end
		elseif climb.phase == "up" then
			pos = pos + V(0, 14 * dt, 0)
			if not wallAhead(14, 6) then climb.phase, climb.clip, climb.t, climb.dur = "end", "ladder_end_r", 0, 2.4
			elseif climb.t >= climb.dur then
				climb.side = climb.side == "l" and "r" or "l"
				climb.clip, climb.t = "ladder_up_" .. climb.side, 0
			end
		else
			pos = pos + (V(0, 11, 0) + fwd * 9) * (dt / climb.dur)
			if climb.t >= climb.dur then climb = nil vy = 0 end
		end
	elseif act then
		local sp = act.sp
		if sp.stun then target = ZERO
		elseif sp.dash then target = fwd * (sp.dash * math.min(1, p * 5) * (p > 0.85 and (1 - p) / 0.15 or 1))
		elseif sp.lunge then target = fwd * (sp.lunge * math.sin(math.pi * p))
		else target = ZERO end
		if sp.turn and p > 0.15 and p < 0.85 then yaw = yaw + sp.turn * dt / (0.7 * act.dur) end
	else
		target = wish.Magnitude > 0.05 and wish.Unit * spd * wish.Magnitude or ZERO
	end
	-- ===== movement (sticks to the ground, jumps, slides along walls) =====
	vel = vel:Lerp(target, math.clamp(dt * (act and 14 or 10), 0, 1))
	local h = V(vel.X, 0, vel.Z)
	if h.Magnitude > 0.05 and not climb then
		local step = h * dt
		local r = Workspace:Raycast(pos + V(0, 5, 0), h.Unit * (step.Magnitude + 3), rayParams)
		if r and r.Normal.Y < 0.6 then
			local n = V(r.Normal.X, 0, r.Normal.Z)
			if n.Magnitude > 0.01 then
				n = n.Unit
				vel = vel - n * math.min(0, vel:Dot(n))
				step = V(vel.X, 0, vel.Z) * dt
			end
		end
		pos = pos + step
	end
	if wish.Magnitude > 0.1 and not atk and not climb then
		local want = math.atan2(-wish.X, -wish.Z)
		yaw = yaw + math.clamp(wrap(want - yaw), -CFG.TURN_RATE * dt, CFG.TURN_RATE * dt)
	end
	local gliding = false
	if not climb then
		if actions.JUMP and grounded and not (atk and atk.fixed) then vy = CFG.JUMP_POWER grounded = false end
		vy = vy - CFG.GRAVITY * dt
		if not grounded and vy < 0 then fallT = fallT + dt else fallT = 0 end
		if fallT > 1.0 and not atk then vy = math.max(vy, -18) gliding = true end   -- glide: long falls slow down
		local ny = pos.Y + vy * dt
		local g = groundBelow(V(pos.X, math.max(pos.Y, ny) + 8, pos.Z), 400)
		if g and ny <= g + 0.05 then
			if vy < -70 and not atk then startAct("land") end   -- hard landing
			ny, vy, grounded = g, 0, true
		elseif not g and ny < pos.Y - 200 then ny, vy = pos.Y, 0
		else grounded = grounded and (g ~= nil and ny - g < 0.3) end
		pos = V(pos.X, ny, pos.Z)
	end
	actions.JUMP = nil
	-- ===== pick animation =====
	local hs = V(vel.X, 0, vel.Z).Magnitude
	local want
	if climb then want = climb.clip
	elseif atk then want = atk.name
	elseif gliding then want = "glide"
	elseif not grounded then want = "run"
	elseif hs > 14 then want = "run"
	elseif hs > 1.2 then want = "walk"
	else want = "idle" end
	-- idle fidgets: after a while standing still he looks around / fixes his hat
	if want == "idle" then
		idleT = idleT + dt
		if idleT > idleNext then idleT, idleNext = 0, 12 + math.random() * 8 startAct(pick(FIDGET)) end
	else idleT = 0 end
	setClip(want)
	local c = getClip(curClip)
	local rate = 1
	if curClip == "walk" or curClip == "run" then rate = math.clamp(hs / c.ref, 0.5, 2.4) end
	if not grounded and not atk and not climb and not gliding then rate = 0.35 end
	curT = curT + dt * rate
	if atk and curT >= atk.dur then
		local after = atk.sp.after
		atk = nil
		if after then startAct(after, true) end
	end
	samplePose(c, curT, newPose)
	if blend < 1 then
		blend = math.min(1, blend + dt / CFG.CLIP_BLEND)
		for b = 1, NB do pose[b] = fromPose[b]:Lerp(newPose[b], blend) end
	else
		for b = 1, NB do pose[b] = newPose[b] end
	end
	local root = CF(pos) * ANGLES(0, yaw, 0)
	-- ===== push the bone drivers (welded plates follow their driver ON THE SERVER, everybody sees it) =====
	moveAcc = moveAcc + dt
	if moveAcc >= 1 / CFG.UPDATE_HZ then
		moveAcc = 0
		local cnt = 0
		for bi, bn in ipairs(BONE_ORDER) do
			local list = byBone[bn]
			if list then
				local Wb = root * pose[bi]
				for i = 1, #list do
					local f = list[i]
					local cf2 = Wb * f.cf
					cnt = cnt + 1
					bulkParts[cnt], bulkCFs[cnt] = f.part, cf2
					f.bp.Position = cf2.Position
					f.bg.CFrame = cf2
				end
			end
		end
		for i = cnt + 1, lastN do bulkParts[i], bulkCFs[i] = nil, nil end
		lastN = cnt
		if cnt > 0 then
			local ok = pcall(Workspace.BulkMoveTo, Workspace, bulkParts, bulkCFs, Enum.BulkMoveMode.FireCFrameChanged)
			if not ok then
				local left = pruneDead()
				lastN = 0
				if left < count * 0.5 then shutdown("the plane was despawned") return end
			end
		end
	end
	-- ===== camera target + keep the real character hidden INSIDE the body =====
	camPart.CFrame = CF(pos + V(0, CFG.CAM_HEIGHT, 0))
	RealRoot.Anchored = true
	RealRoot.CFrame = root * CF(0, 7 * U / 6, 0)
	RealRoot.AssemblyLinearVelocity = ZERO
	hideT = hideT + dt
	if hideT > 0.25 then
		hideT = 0
		for _, d in ipairs(Character:GetDescendants()) do
			if d:IsA("BasePart") then
				d.CanCollide = false
				if CFG.HIDE_SELF then d.LocalTransparencyModifier = 1 end
			end
		end
	end
	fastCam = fastCam + dt
	if fastCam > 1 then
		fastCam = 0
		rayParams.FilterDescendantsInstances = listExclude()
		if cam.CameraSubject ~= camPart then cam.CameraSubject = camPart end
	end
end
local errCount = 0
track(RunService.Heartbeat:Connect(function(dt)
	if not alive then return end
	local ok, err = pcall(frame, dt)
	if ok then errCount = 0
	else
		errCount = errCount + 1
		if errCount == 1 then warn("[Tyrant] frame error: " .. tostring(err)) end
		if errCount > 90 then shutdown("too many errors: " .. tostring(err)) end
	end
end))
----------------------------------------------------------------------
-- INPUT (PC; phones use the buttons above + the default thumbstick/jump)
----------------------------------------------------------------------
track(UIS.InputBegan:Connect(function(input, gp)
	if not alive then return end
	local k = input.KeyCode
	if k == Enum.KeyCode.LeftShift then shiftHeld = true end
	if gp then return end
	if input.UserInputType == Enum.UserInputType.MouseButton1 or k == Enum.KeyCode.F then actions.ATTACK = true
	elseif k == Enum.KeyCode.T then actions.TAUNT = true
	elseif k == Enum.KeyCode.R then actions.HEAVY = true
	elseif k == Enum.KeyCode.C then actions.CHARGE = true
	elseif k == Enum.KeyCode.Q then actions.USE = true
	elseif k == Enum.KeyCode.G then actions.PLAY = "att_grab"
	elseif k == Enum.KeyCode.V then actions.PLAY = (math.random() < 0.5 and "att_turn_l90" or "att_turn_r90")
	elseif k == Enum.KeyCode.Z then actions.PLAY = "att_turn180_1"
	elseif k == Enum.KeyCode.E or input.UserInputType == Enum.UserInputType.MouseButton2 then actions.SLASH = true
	elseif k == Enum.KeyCode.H then hudLabel.Visible = not hudLabel.Visible
	elseif k == Enum.KeyCode.P then shutdown("P pressed")
	end
end))
track(UIS.InputEnded:Connect(function(input)
	if input.KeyCode == Enum.KeyCode.LeftShift then shiftHeld = false end
end))
track(UIS.JumpRequest:Connect(function() actions.JUMP = true end))
----------------------------------------------------------------------
-- WATCHDOG
----------------------------------------------------------------------
track(RealHum.Died:Connect(function() shutdown("you died") end))
track(Player.CharacterAdded:Connect(function() shutdown("respawned") end))
track(Character.AncestryChanged:Connect(function(_, parent) if not parent then shutdown("character removed") end end))
track(aircraft.AncestryChanged:Connect(function(_, parent) if not parent then shutdown("plane despawned") end end))
task.spawn(function()
	while alive do
		task.wait(0.25)
		if not aircraft.Parent or not aircraft:IsDescendantOf(Workspace) then shutdown("plane despawned") break end
		if not Character.Parent or RealHum.Health <= 0 then shutdown("character gone") break end
	end
end)
startAct("emerge_2")
say("Tyrant T-501 online.")
say("PC: WASD move | SHIFT run | SPACE jump | LMB/F punch combo | RMB/E slash combo | R heavy | C charge | G grab | V/Z spin attacks")
say("T taunt (rage speed) | Q use doors/buttons | walk into a wall to CLIMB | long fall = glide | hit = stun/knockdown | H hud | P stop")
say("Mobile: thumbstick move | jump button | ATTACK / SLASH / RUN / ANIMS (all 60 animations) buttons")
end
